    case acceleration(value: Vector3, timestampS: Double
    )
    case rotationRate(value: Vector3, timestampS: Double
    )
    case magneticField(value: Vector3, timestampS: Double
    )
    case deviceMotion(sample: DeviceMotionSample, timestampS: Double
    )
    case altitude(
        /**
         * Metres up (or down) since the updates started.
         */relativeAltitudeM: Double, pressureKpa: Double, timestampS: Double
    )
    /**
     * The sensor stopped with an error (for example the motion
     * permission was refused). No more updates follow.
     */
    case failed(sensor: MotionSensor, reason: String
    )





}

