    typealias SwiftType = MotionReading

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MotionReading {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .acceleration(value: try FfiConverterTypeVector3.read(from: &buf), timestampS: try FfiConverterDouble.read(from: &buf)
        )
        
        case 2: return .rotationRate(value: try FfiConverterTypeVector3.read(from: &buf), timestampS: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .magneticField(value: try FfiConverterTypeVector3.read(from: &buf), timestampS: try FfiConverterDouble.read(from: &buf)
        )
        
        case 4: return .deviceMotion(sample: try FfiConverterTypeDeviceMotionSample.read(from: &buf), timestampS: try FfiConverterDouble.read(from: &buf)
        )
        
        case 5: return .altitude(relativeAltitudeM: try FfiConverterDouble.read(from: &buf), pressureKpa: try FfiConverterDouble.read(from: &buf), timestampS: try FfiConverterDouble.read(from: &buf)
        )
        
        case 6: return .failed(sensor: try FfiConverterTypeMotionSensor.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MotionReading, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .acceleration(value,timestampS):
