private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_forge_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_services() != 51324) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_native_services_installed() != 37330) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_native_services_version() != 54155) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_parse_deep_link() != 63697) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_bluetooth() != 22127) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_connectivity() != 36487) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_device_status() != 30239) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_location() != 13107) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_func_install_native_motion() != 32256) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_method_devicelab_refresh_permissions() != 63463) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_forge_ffi_checksum_method_devicelab_request_permission() != 64253) {
